import {Pressable,Text,View} from "react-native";
import {joinClasses} from "@/components/nyc-tron/ui/components/styles";

/**
 * Labeled on/off row shared by the canvas settings panels: a 44pt switch with
 * the label on the start side and the track on the end side (mirrored in RTL).
 */
export function SettingSwitch({label,on,onChange,disabled,styled,hint}:{
  label:string;on:boolean;onChange:(on:boolean)=>void;disabled:boolean;styled:boolean;hint?:string|undefined;
}){
  return <Pressable role="switch" aria-checked={on} accessibilityRole="switch" accessibilityState={{checked:on,disabled}}
    aria-label={label} accessibilityHint={hint} disabled={disabled} onPress={()=>onChange(!on)}
    {...{className:joinClasses(styled&&"rounded-control focus-visible:ring-2 focus-visible:ring-focus")}}
    style={{minHeight:44,flexDirection:"row",alignItems:"center",justifyContent:"space-between",gap:12,paddingHorizontal:4,opacity:disabled?0.5:1}}>
    <Text {...{className:joinClasses(styled&&"text-text text-sm")}} style={{flexShrink:1}}>{label}</Text>
    <View pointerEvents="none" {...{className:joinClasses(styled&&"border",styled&&(on?"bg-primary border-primary":"bg-surface-sunken border-border"))}}
      style={{width:40,height:24,borderRadius:12,padding:2,justifyContent:"center",alignItems:on?"flex-end":"flex-start"}}>
      <View {...{className:joinClasses(styled&&(on?"bg-on-primary":"bg-text-muted"))}} style={{width:18,height:18,borderRadius:9}}/>
    </View>
  </Pressable>;
}

import {useRef,type ReactNode} from 'react';
import {Text,View,type ViewProps} from 'react-native';
import {createStore} from 'zustand/vanilla';
import {useStore} from 'zustand';
import {Select} from '@/components/nyc-tron/ui/components/Select';
import {UnitInput} from '@/components/nyc-tron/ui/components/shell/UnitInput';
import {Button} from '@/components/nyc-tron/ui/components/Button';
import {ErrorMessage} from '@/components/nyc-tron/ui/components/feedback/ErrorMessage';
import {useOwnedAction} from '@/components/nyc-tron/ui/components/shell/useOwnedAction';
import {SettingSwitch} from '@/components/nyc-tron/ui/components/forge/canvas/SettingSwitch';
import {joinClasses} from '@/components/nyc-tron/ui/components/styles';
import type {ProfileColor} from '@/components/nyc-tron/ui/components/forge/color/color-management';
import {validatePhotoRange,validatePhotoImageSize,type PhotoRangeMask,type PhotoImageSize,type PhotoMaskCombine} from '@/components/nyc-tron/ui/components/forge/photo/photo-masks';
export type {PhotoRangeMask} from '@/components/nyc-tron/ui/components/forge/photo/photo-masks';
export interface PhotoRangeSampleRequest {readonly photoId:string;readonly expectedRevision:string;readonly x:number;readonly y:number}
export interface LuminanceColorRangeMaskProps extends Omit<ViewProps,'children'> {
 readonly photoId:string;readonly revision:string;readonly imageSize:PhotoImageSize;readonly value:PhotoRangeMask;
 readonly onChange:(mask:PhotoRangeMask)=>void;
 readonly onSample:(request:PhotoRangeSampleRequest,signal:AbortSignal)=>{readonly luminance:number;readonly color:ProfileColor}|Promise<{readonly luminance:number;readonly color:ProfileColor}>;
 readonly children?:ReactNode;readonly disabled?:boolean;readonly unstyled?:boolean;
}
const makeStore=()=>createStore(()=>({x:0,y:0}));
/** Document-only sampling: profile-bearing color is retained, never inferred from an OS screenshot. */
export function LuminanceColorRangeMask({photoId,revision,imageSize,value,onChange,onSample,children,disabled=false,unstyled=false,...props}:LuminanceColorRangeMaskProps){
 validatePhotoRange(value);validatePhotoImageSize(imageSize);if(!photoId.trim())throw new TypeError('Range sampling requires a photo identity');
 const action=useOwnedAction(JSON.stringify([photoId,revision])),locked=disabled||action.pending!==null;
 const local=useRef<ReturnType<typeof makeStore>|null>(null);local.current??=makeStore();const store=local.current,point=useStore(store,s=>s);
 const set=(change:Partial<PhotoRangeMask>)=>{if(locked)return;const next={...value,...change};validatePhotoRange(next);onChange(next);};
 return <View {...props} style={[{gap:8},props.style]}>
  <Select label="Photo range mask kind" value={value.mode} options={[{value:'luminance',label:'Luminance range'},{value:'color',label:'Color range'}]} disabled={locked} unstyled={unstyled} onValueChange={mode=>set({mode:mode as PhotoRangeMask['mode']})}/>
  <UnitInput label="Normalized mask luminance minimum" value={value.minimum} min={0} max={value.maximum} step={.01} disabled={locked||value.mode!=='luminance'} unstyled={unstyled} onCommit={minimum=>set({minimum})}/>
  <UnitInput label="Normalized mask luminance maximum" value={value.maximum} min={value.minimum} max={1} step={.01} disabled={locked||value.mode!=='luminance'} unstyled={unstyled} onCommit={maximum=>set({maximum})}/>
  <UnitInput label="Color range tolerance" value={value.tolerance} min={0} max={1} step={.01} disabled={locked||value.mode!=='color'} unstyled={unstyled} onCommit={tolerance=>set({tolerance})}/>
  <UnitInput label="Photo range softness" value={value.softness} min={0} max={1} step={.01} disabled={locked} unstyled={unstyled} onCommit={softness=>set({softness})}/>
  <Select label="Photo range combination" value={value.combine} options={['replace','add','subtract','intersect'].map(value=>({value,label:value}))} disabled={locked} unstyled={unstyled} onValueChange={combine=>set({combine:combine as PhotoMaskCombine})}/>
  <SettingSwitch label="Invert photo range mask" on={value.invert} onChange={invert=>set({invert})} disabled={locked} styled={!unstyled}/>
  <UnitInput label="Range sample image x" value={Math.min(point.x,imageSize.width-1)} min={0} max={imageSize.width-1} step={1} precision={0} disabled={locked} unstyled={unstyled} onCommit={x=>store.setState({x:Math.round(x)})}/>
  <UnitInput label="Range sample image y" value={Math.min(point.y,imageSize.height-1)} min={0} max={imageSize.height-1} step={1} precision={0} disabled={locked} unstyled={unstyled} onCommit={y=>store.setState({y:Math.round(y)})}/>
  <Button title="Sample photo range" disabled={locked} unstyled={unstyled} onPress={()=>{if(locked)return;const request={photoId,expectedRevision:revision,x:Math.min(point.x,imageSize.width-1),y:Math.min(point.y,imageSize.height-1)};void action.run('sample',async signal=>{const sample=await onSample(request,signal);if(!Number.isFinite(sample.luminance)||sample.luminance<0||sample.luminance>1)throw new RangeError('Sampler must report normalized luminance');const next={...value,color:sample.color,...(value.mode==='luminance'?{minimum:Math.max(0,sample.luminance-.05),maximum:Math.min(1,sample.luminance+.05)}:{})};validatePhotoRange(next);return next;},onChange);}}/>
  <Text {...{className:joinClasses(!unstyled&&'text-text')}}>{value.color?`${value.color.profileId}: ${value.color.channels.join(', ')}; alpha ${value.color.alpha}`:'No document color sample'}</Text>
  {children}
  {action.pending!==null?<Button title="Cancel range sample" unstyled={unstyled} onPress={action.cancel}/>:null}
  <ErrorMessage {...(action.error?{message:action.error}:{})} unstyled={unstyled}/>
 </View>;
}

import { createStore } from "zustand/vanilla";

/** UI request state. Abort controllers stay in the owner's closure. */
export interface ActionState { readonly pending: string | null; readonly error: string | null }
export function createActionOwner(currentScope: () => string) {
  const store = createStore<ActionState>(() => ({ pending: null, error: null }));
  let active = false;
  let current: { readonly scope: string; readonly abort: AbortController } | null = null;
  function cancel() {
    const previous = current; current = null;
    previous?.abort.abort();
  }
  return {
    store,
    activate() { cancel(); active = true; store.setState({ pending: null, error: null }); },
    deactivate() { active = false; cancel(); },
    cancel() { cancel(); store.setState({ pending: null }); },
    async run<T>(id: string, operation: (signal: AbortSignal) => T | Promise<T>, consume?: (value: T) => void, options?: { pendingForAsyncOnly?: boolean }): Promise<boolean> {
      if (!active) return false;
      cancel();
      const request = { scope: currentScope(), abort: new AbortController() };
      current = request;
      const valid = () => active && current === request && request.scope === currentScope();
      if (options?.pendingForAsyncOnly) store.setState({ error: null });
      else store.setState({ pending: id, error: null });
      try {
        if (!valid()) return false;
        const result = operation(request.abort.signal);
        let value: T;
        if (options?.pendingForAsyncOnly) {
          if (result && typeof (result as Promise<T>).then === 'function') {
            // A synchronous acknowledgement or already-resolved promise must not
            // disable (and blur) the focused control between keyboard commands.
            let settled = false;
            const completion = Promise.resolve(result).then(value => { settled = true; return value; }, error => { settled = true; throw error; });
            void Promise.resolve().then(() => { if (!settled && valid()) store.setState({ pending: id, error: null }); });
            value = await completion;
          } else value = result as T;
        } else value = await result;
        if (!valid()) return false;
        consume?.(value);
        if (!valid()) return false;
        store.setState({ pending: null });
        return true;
      } catch (error) {
        if (!valid()) return false;
        store.setState({ pending: null, error: error instanceof Error ? error.message : String(error) });
        return false;
      } finally { if (current === request) current = null; }
    },
  };
}

import { useLayoutEffect, useRef } from "react";
import { useStore } from "zustand";
import { createActionOwner } from "@/components/nyc-tron/ui/components/shell/action-owner";

/** Cancel stale requests at the committed document boundary, before new controls accept input. */
export function useOwnedAction(scope: string) {
  const committed = useRef(scope);
  const ref = useRef<ReturnType<typeof createActionOwner> | null>(null);
  ref.current ??= createActionOwner(() => committed.current);
  const owner = ref.current;
  useLayoutEffect(() => {
    committed.current = scope;
    owner.activate();
    return () => owner.deactivate();
  }, [owner, scope]);
  const state = useStore(owner.store, value => value);
  const run: typeof owner.run = (id, operation, consume, options) => committed.current === scope ? owner.run(id, operation, consume, options) : Promise.resolve(false);
  return { ...state, run, cancel: owner.cancel };
}

/**
 * Tailwind classes are merged at the APP boundary. Joining without
 * tailwind-merge avoids deleting custom typography/color utilities that
 * depend on each consumer's own @theme configuration.
 */
export function joinClasses(...items: Array<string|false|null|undefined>):string {
  return items.filter(Boolean).join(" ");
}
